import java.io.*;
import java.util.*;

public class CF1187G extends PrintWriter {
    public CF1187G() { super(System.out); }

    static class Reader {
        private final BufferedReader br;
        private StringTokenizer st;

        Reader(InputStream in) { br = new BufferedReader(new InputStreamReader(in)); }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(next()); }
    }

    Reader reader;

    public static void main(String[] args) {
        new CF1187G().solve();
    }

    static final int INF = 0x3f3f3f3f;
    List<Integer>[] adjList;
    int nodeCount, edgeCount;
    int[] pi, d, prevEdgeIdx;
    int[] u, v, uv, cost;
    int[] cap;

    void setup(int n, int m) {
        adjList = new ArrayList[n];
        for (int i = 0; i < n; i++) adjList[i] = new ArrayList<>();
        pi = new int[n];
        d = new int[n];
        prevEdgeIdx = new int[n];
        u = new int[m];
        v = new int[m];
        uv = new int[m];
        cost = new int[m];
        cap = new int[m * 2];
        edgeCount = 0;
    }

    void connect(int a, int b, int capacity, int c) {
        int idx = edgeCount++;
        u[idx] = a;
        v[idx] = b;
        uv[idx] = a ^ b;
        cost[idx] = c;
        cap[idx * 2] = capacity;
        adjList[a].add(idx * 2);
        adjList[b].add(idx * 2 + 1);
    }

    int[] queueArr;
    int qStart, qLen, qCap;
    boolean[] inQ;

    void push(int node) {
        if (inQ[node]) return;
        if (qStart + qLen == queueArr.length) {
            if (qLen * 2 <= queueArr.length) {
                System.arraycopy(queueArr, qStart, queueArr, 0, qLen);
                qStart = 0;
            } else {
                int[] tmp = new int[queueArr.length * 2];
                System.arraycopy(queueArr, qStart, tmp, 0, qLen);
                queueArr = tmp;
                qStart = 0;
            }
        }
        queueArr[qStart + qLen++] = node;
        inQ[node] = true;
    }

    int pop() {
        int node = queueArr[qStart++];
        qLen--;
        inQ[node] = false;
        return node;
    }

    boolean bellmanFord(int src, int dst) {
        Arrays.fill(pi, INF);
        pi[src] = 0;
        qStart = qLen = 0;
        push(src);

        while (qLen > 0) {
            int x = pop();
            int nd = d[x] + 1;

            for (int e : adjList[x]) {
                if (cap[e] > 0) {
                    int idx = e >> 1;
                    int c = (e & 1) == 0 ? cost[idx] : -cost[idx];
                    int np = pi[x] + c;
                    int y = x ^ uv[idx];

                    if (pi[y] > np || (pi[y] == np && d[y] > nd)) {
                        pi[y] = np;
                        d[y] = nd;
                        prevEdgeIdx[y] = e;
                        push(y);
                    }
                }
            }
        }
        return pi[dst] != INF;
    }

    void augment(int s, int t) {
        int minCap = INF;
        for (int cur = t; cur != s; cur ^= uv[prevEdgeIdx[cur] >> 1]) {
            minCap = Math.min(minCap, cap[prevEdgeIdx[cur]]);
        }
        for (int cur = t; cur != s; cur ^= uv[prevEdgeIdx[cur] >> 1]) {
            int idx = prevEdgeIdx[cur];
            cap[idx] -= minCap;
            cap[idx ^ 1] += minCap;
        }
    }

    void augmentUnit(int s, int t) {
        for (int cur = t; cur != s; cur ^= uv[prevEdgeIdx[cur] >> 1]) {
            int idx = prevEdgeIdx[cur];
            cap[idx]--;
            cap[idx ^ 1]++;
        }
    }

    int minCostFlow(int s, int t) {
        while (bellmanFord(s, t)) {
            augmentUnit(s, t);
        }
        int total = 0;
        for (int i = 0; i < edgeCount; i++) {
            total += cost[i] * cap[i * 2 + 1];
        }
        return total;
    }

    void solve() {
        try {
            reader = new Reader(System.in);
            int n = reader.nextInt();
            int m = reader.nextInt();
            int k = reader.nextInt();
            int c = reader.nextInt();
            int d = reader.nextInt();

            int[] special = new int[k];
            for (int i = 0; i < k; i++) special[i] = reader.nextInt() - 1;

            List<Integer>[] g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                int a = reader.nextInt() - 1;
                int b = reader.nextInt() - 1;
                g[a].add(b);
                g[b].add(a);
            }

            int T = k + 1;
            int totalNodes = n * T + 1;
            int totalEdges = k + (m * 2 * k + n) * (T - 1);
            setup(totalNodes, totalEdges);

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    for (int w : g[i]) {
                        int v = w * T + t + 1;
                        for (int x = 1; x <= k; x++) {
                            connect(u, v, 1, c + (x * 2 - 1) * d);
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    int v = u + 1;
                    connect(u, v, k, i == 0 ? 0 : c);
                }
            }

            for (int i = 0; i < k; i++) {
                connect(totalNodes - 1, special[i] * T, 1, 0);
            }

            println(minCostFlow(totalNodes - 1, 0 * T + T - 1));
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
